CREATE TYPE game_status AS ENUM ('waiting_for_opponent','ready_check','in_progress','finalizing','completed');
CREATE TYPE player_status AS ENUM ('joined','ready','playing','finished');
CREATE TYPE round_status AS ENUM ('not_started','active','finished','expired');
CREATE TYPE rematch_status AS ENUM ('requested','accepted','declined');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL, is_synthetic boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chat_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, provider_user_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider, provider_user_id));
CREATE INDEX chat_identity_user_idx ON chat_identities(user_id);
CREATE TABLE auth_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, csrf_hash text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX auth_session_user_idx ON auth_sessions(user_id);
CREATE TABLE games (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), status game_status NOT NULL DEFAULT 'waiting_for_opponent', rack text NOT NULL CHECK (rack ~ '^[a-z]{6}$'), rules jsonb NOT NULL, version integer NOT NULL DEFAULT 0, created_by_user_id uuid NOT NULL REFERENCES users(id), parent_game_id uuid UNIQUE REFERENCES games(id), winner_player_id uuid, finalized_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE game_players (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), seat smallint NOT NULL CHECK (seat BETWEEN 1 AND 2), status player_status NOT NULL DEFAULT 'joined', score integer NOT NULL DEFAULT 0, valid_word_count integer NOT NULL DEFAULT 0, joined_at timestamptz NOT NULL DEFAULT now(), ready_at timestamptz, UNIQUE(game_id,seat), UNIQUE(game_id,user_id));
CREATE INDEX game_player_user_idx ON game_players(user_id);
ALTER TABLE games ADD CONSTRAINT game_winner_player_fk FOREIGN KEY (winner_player_id) REFERENCES game_players(id);
CREATE TABLE rounds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, game_player_id uuid NOT NULL UNIQUE REFERENCES game_players(id) ON DELETE CASCADE, status round_status NOT NULL DEFAULT 'not_started', version integer NOT NULL DEFAULT 0, started_at timestamptz, expires_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX round_due_idx ON rounds(status,expires_at);
CREATE TABLE word_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), round_id uuid NOT NULL REFERENCES rounds(id) ON DELETE CASCADE, normalized_word text NOT NULL, submitted_word text NOT NULL, accepted boolean NOT NULL, rejection_code text, score integer NOT NULL DEFAULT 0, idempotency_key uuid NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(round_id,idempotency_key));
CREATE UNIQUE INDEX submission_accepted_word_uq ON word_submissions(round_id,normalized_word) WHERE accepted=true;
CREATE INDEX submission_round_idx ON word_submissions(round_id,received_at);
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, created_by_player_id uuid NOT NULL REFERENCES game_players(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz, used_by_user_id uuid REFERENCES users(id), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX invitation_game_idx ON invitations(game_id);
CREATE TABLE rematch_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_game_id uuid NOT NULL REFERENCES games(id) ON DELETE CASCADE, requested_by_player_id uuid NOT NULL REFERENCES game_players(id), status rematch_status NOT NULL DEFAULT 'requested', resulting_game_id uuid UNIQUE REFERENCES games(id), created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, UNIQUE(source_game_id,requested_by_player_id));
